// js
// LPA s.67 para 1: an employer who ends the employment without a s.119 ground pays the annual holidays of the year of
// termination in proportion to the s.30 entitlement. s.67 para 2: on any termination, the untaken days accumulated under
// s.30 para 3 are paid.
const employment = ctx.subject.employment;
const facts = get(employment, 'employee_extension_data', {});
const end = get(employment, 'effective_range.to', ctx.as_of);
const started = get(employment, 'service_started_on', employment.effective_range.from);
const year = Math.floor(calendar_completed_months(started, end) / 12);
const grant = year * 12 >= ctx.lookup.service_months ? ctx.lookup.grant_days : 0;
const current = Math.min(ctx.entry.quantity, grant);
const dismissed =
  ['DISMISSAL', 'DISMISSAL_FOR_CAUSE', 'REDUNDANCY', 'RETIREMENT', 'END_OF_CONTRACT'].includes(get(facts, 'exit_ground', '')) &&
  get(facts, 'section_119_ground', false) !== true;
const served = calendar_completed_months(add_months(started, 12 * year), add_days(end, 1));
const owed = dismissed ? Math.max(0, current - (grant * (12 - served)) / 12) : 0;
return ctx.day_rate * (ctx.entry.quantity - current + owed);
